    const sunVisible = (p: any) => {
      const cs = dot(p, sun), perp = sqrt(max(dot(p, p).sub(cs.mul(cs)), 0));
      return select(cs.greaterThan(0), float(1), smoothstep(R - 2, R + 6, perp));
