    };
    const phase = (mu: any) => {
      const pR = float(3 / (16 * Math.PI)).mul(mu.mul(mu).add(1)), g2 = G * G;
      const pM = float((3 / (8 * Math.PI)) * (1 - g2) / (2 + g2)).mul(mu.mul(mu).add(1)).div(pow(max(float(1 + g2).sub(mu.mul(2 * G)), 1e-4), 1.5));
      return { pR, pM };
