        const x = ro.add(rd.mul(tA.add(segV.mul(float(i).add(0.5))))).toVar();
        const h = length(x).sub(R).toVar();
        const dR = exp(h.negate().div(HR)).mul(segV).toVar(), dM = exp(h.negate().div(HM)).mul(segV).toVar();
