  }

  step(dt: number) {
    const k = 1 - Math.exp(-dt * 5);
    this.yaw += (this.tYaw - this.yaw) * k; this.pitch += (this.tPitch - this.pitch) * k; this.dist += (this.tDist - this.dist) * k;
    const c = Math.cos(this.pitch);
