  double f = 1.0 - C * (chi2 / r0), g = dt - chi * chi2 * S / smu;
  V3 r = add(mul(s.r, f), mul(s.v, g));
  double rm = len(r);
  double fd = (S * (chi * z) - chi) * (smu / (r0 * rm)), gd = 1.0 - C * (chi2 / rm);
  return {r, add(mul(s.r, fd), mul(s.v, gd))};
