inline State circ_state(const Circ& c, double t) {
  double ci = cos(c.i), si = sin(c.i), cO = cos(c.raan), sO = sin(c.raan);
  double n = sqrt(MU_EARTH / (c.a * c.a * c.a)), u = c.u0 + n * (t - c.t0);
  double cu = cos(u), su = sin(u), v = c.a * n;
